/// <summary>
/// The MobCountOrderTypeTagCount class is the class handling the Tag count orders.
/// </summary>
[TFMTableNameAttribute(tableStr(InventJournalTable), 'TagCount')]
class MobCountOrderTypeTagCount extends MobCountOrderType
{
    InventJournalTable          InventJournalTable;
}

Method.Source:
    /// <summary>
    ///
    /// </summary>
    /// <param name = "_filters">MobRequestFiltersElement element</param> 
    /// <param name = "_scannedValue"></param>
    /// <returns></returns>
    public Map getHeaderRecords(TFMRequestFiltersElement _filters, str _scannedValue)
    {
        Map ret = new Map(Types::String, Types::Record);

        InventJournalTrans_Tag  inventJournalTrans_Tag;
		if (true)
        {
            return ret;
        }
        while select inventJournalTable
            where inventJournalTable.JournalType == InventJournalType::TagCounting &&
                  inventJournalTable.Posted == NoYes::No &&
                  inventJournalTable.MobReleasedToMobile
            exists join inventJournalTrans_Tag
                where inventJournalTrans_Tag.JournalId == inventJournalTable.JournalId &&
                      !inventJournalTrans_Tag.MobRegisteredOnMobile
        {
            ret.insert(this.getBackendID(inventJournalTable),inventJournalTable);
            //MobXMLFormat = TFMXMLFormat::constructFromCommon(resultXml, inventJournalTable, sorting);
            //MobXMLFormat.run();
        }

        return ret;
    }

/// <summary>
///
/// </summary>
/// <param name = "_request">MobRequestGetOrderLinesElement element</param>
/// <returns></returns>
public Map getLineRecords(TFMRequestGetOrderLinesElement _request)
{
    Map ret = new Map(Types::String, Types::Record);        
    inventJournalTrans_Tag  inventJournalTrans_Tag;
    InventJournalId         journalId;

    journalId = this.getJournalId(_request.parmBackendID()); 

    while select inventJournalTrans_Tag
                where inventJournalTrans_Tag.JournalId == journalId &&
                      !inventJournalTrans_Tag.MobRegisteredOnMobile
    {

        ret.insert(int642str(inventJournalTrans_Tag.RecId),inventJournalTrans_Tag);

    }

    return ret;
}

public str getBackendID(Common _common)
{
    InventJournalTable = _common;
    return tableStr(InventJournalTable) + '/' + fieldStr(InventJournalTable,JournalId) + '/' + InventJournalTable.JournalId + '/' + 'TagCount';
}

